TP.register({id:"lp6-g1",lp:6,grade:"1",mode:"curriculum",checks:5,nextGrade:"2nd grade",build(E){const F=E.F;const HOUSE="cabin",TREE="tree",BRIDGE="bridge",STAR="star",STARS="star",MOON="moon",SPARK="burst",OWL="owl",CAT="cat",BOOT="boot",HAT="topHat",COCOA="cocoa",BOOK="books",SCOPE="telescope",EAR="ear";const ic=(e,px)=>(F.icon||F.pic2)(e,px)||e;const K_EYE=window.TP_ICON_EYE||((x,y,r)=>`<circle cx="${x}" cy="${y}" r="${r||4.4}" fill="#4A332A"/><circle cx="${x-1.4}" cy="${y-1.7}" r="1.6" fill="#fff"/>`);const K_BLUSH=window.TP_ICON_BLUSH||((x,y)=>`<ellipse cx="${x}" cy="${y}" rx="6.5" ry="4.2" fill="#F49AAB" opacity=".9"/>`);const K_SMILE=window.TP_ICON_SMILE||((x,y,w)=>`<path d="M${x-w} ${y} q${w} ${w} ${w*2} 0" fill="none" stroke="#4A332A" stroke-width="2.6" stroke-linecap="round"/>`);const K_FACE=window.TP_ICON_FACE||((cx,cy,sp,mw)=>K_EYE(cx-sp,cy)+K_EYE(cx+sp,cy)+K_BLUSH(cx-sp-7,cy+9)+K_BLUSH(cx+sp+7,cy+9)+K_SMILE(cx,cy+9,mw||4));const n1=v=>Math.round(v*10)/10;const at=(x,y,k,inner)=>`<g transform="translate(${n1(x)} ${n1(y)}) scale(${n1(k)})">${inner}</g>`;const INK="#6B4A3C",ROSE="#F7A8A0",GOLDL="#FBD873",BRASS="#D9A066",CREAM="#FBF1E4",NIGHT="#453F80",STREET="#5B5496",STARC="#FBF3D6",POLE="#8C86C4";function lanternShape(x,y,s,c){return TP_LANT(x,y,s/44,c,false)}const lanternSvg=(w,c)=>`<svg viewBox="0 0 ${w} ${Math.round(w*1.5)}" width="${w}" style="vertical-align:middle" role="img" aria-label="a paper lantern">${lanternShape(w*.5,w*.78,w*.9,c)}</svg>`;const TOWN="Tonight our town looks like a big bowl. The bowl is full of light. Long ropes hang over the main street. On each rope there are ten paper lanterns. My job is to light the very last one. I climb three steps. I reach up high. The paper glows gold. The whole street turns warm. Then I run down to the bridge. The river is black and still. It holds every lantern in it. I count them twice.";const LANTERN="Noor made a lantern out of red paper and thin sticks. She carried it down to the river to hang it up with all the others. But the last hook on the rope was too high, and she could not reach it. She stretched up on her toes, but it was no use. Then Tam ran over with a crate. Noor could stand on it! She climbed up and hooked her lantern on at the end of the rope. Then the two friends sat on the bridge and watched the lantern swing.";const LAMPLIGHTER="Long ago, before a town had electric lights, a lamplighter walked the streets at dusk. The lamplighter carried a long pole with a small flame on the end and lit the oil lamps on the corners, one at a time. In the morning the same walk happened again, and every flame went out. People knew what time it was by watching the lamplighter go by. When towns got electric lights, the job went away, but the word lamplighter stayed.";const CREW="The lantern crew works in the cold. They string a rope between two tall poles and clip a paper lantern on every two feet. A worker on a short ladder checks each hook before the lights go on. If one lantern hangs lower than the rest, the rope looks crooked from the bridge, so the crew measures as they go.";const WORDS=["chin","bank","glow","bell","home","night","street","star","lifted","moonlight","river","zide"];function story(title,text){return`<p class="big" style="text-align:center;margin:0 0 6px">${title}</p><p class="passage">${text}</p>`}const nightBox=(w,h)=>`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="${NIGHT}" stroke="var(--line)" stroke-width="4"/>`;const skyDots=(w,n,seed)=>{let x=seed||11,out="";const rnd=()=>{x=(x*9301+49297)%233280;return x/233280};for(let i=0;i<n;i++)out+=`<circle cx="${(18+rnd()*(w-36)).toFixed(0)}" cy="${(14+rnd()*70).toFixed(0)}" r="${i%3?2:2.6}" fill="${STARC}" opacity="${i%2?".8":".95"}"/>`;return out};function ropeRow(n){const w=620,h=150,x0=40,x1=w-40,sag=22,ry=x=>{const t=(x-x0)/(x1-x0);return 44+4*sag*t*(1-t)};let b=nightBox(w,h)+skyDots(w,6,7);b+=`<path d="M${x0} 44 Q${(x0+x1)/2} ${44+2*sag} ${x1} 44" fill="none" stroke="${INK}" stroke-width="5" stroke-linecap="round"/>`;const cols=[ROSE,GOLDL,"#C9A6EC","#9FD6F0","#F6B3D0"];for(let i=0;i<n;i++){const x=x0+(i+.5)*(x1-x0)/n;b+=lanternShape(x,ry(x)+26,44,cols[i%5])}return`<svg viewBox="0 0 ${w} ${h}" width="600" role="img" aria-label="A rope across the street with ${n} paper lanterns hanging from it">${b}</svg>`}function lanternGrid(n,per){const cell=74,rows=Math.ceil(n/per),w=per*cell+20,h=rows*cell+24;let b=`<rect x="3" y="3" width="${w-6}" height="${h-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;const cols=[GOLDL,ROSE];for(let i=0;i<n;i++)b+=lanternShape(10+i%per*cell+cell/2,16+Math.floor(i/per)*cell+cell/2,56,cols[Math.floor(i/per)%2]);return`<svg viewBox="0 0 ${w} ${h}" width="${Math.min(w,620)}" role="img" aria-label="${n} paper lanterns">${b}</svg>`}function unitFig(){const u=52,y1=58,y2=160,W=460;let s=`<svg viewBox="0 0 ${W} 230" width="440" role="img" aria-label="A rope above six blocks laid end to end, and a scarf above four blocks laid end to end.">`;s+=`<rect x="3" y="3" width="${W-6}" height="224" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;s+=`<path d="M40 ${y1-10} h${6*u}" stroke="${BRASS}" stroke-width="10" stroke-linecap="round" fill="none"/>`;for(let i=0;i<6;i++)s+=`<rect x="${40+i*u}" y="${y1}" width="${u}" height="28" fill="${GOLDL}" stroke="${INK}" stroke-width="2.5"/>`;s+=`<text x="40" y="${y1+52}" font-size="22" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)">rope</text>`;s+=`<path d="M40 ${y2-10} h${4*u}" stroke="#C9A6EC" stroke-width="12" stroke-linecap="round" fill="none"/>`;for(let i=0;i<4;i++)s+=`<rect x="${40+i*u}" y="${y2}" width="${u}" height="28" fill="${GOLDL}" stroke="${INK}" stroke-width="2.5"/>`;s+=`<text x="40" y="${y2+52}" font-size="22" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)">scarf</text>`;s+=`<text x="${W-20}" y="26" font-size="19" text-anchor="end" font-family="Andika,sans-serif" font-weight="700" fill="var(--muted)">Every block is the same size.</text>`;return s+"</svg>"}function packList(){return F.table(["What we take","What it is for"],[[`${lanternSvg(34,ROSE)} a lantern`,"to see the path in the dark"],[`${ic(HAT,30)} a hat`,"to keep your ears warm"],[`${ic(BOOK,30)} a small notebook`,"to write down what you see"],[`${ic(COCOA,30)} a cup of cocoa`,"to warm your hands on the bridge"]],{caption:"Night Walk Pack List"})}const TWO=`<ul class="qlist" style="margin-top:14px"><li>Write 2 or 3 sentences.</li></ul>`;const WDIR="Write on your paper. When you finish, hold it up and read it to your teacher.";const STARS_TEXT="Stars are very big, and they are very hot. But stars look small to us. That is because they are very far away. Our sun is a star too. The sun looks big and bright because it is much closer to us than any other star.";const labG=(x,y,t,sz)=>`<text x="${x}" y="${y}" font-size="${sz||24}" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle">${t}</text>`;const CLOCKS_G1=[["A",6,0],["B",8,30],["C",10,0]];function clockRowG1(){return`<div class="figure" style="gap:18px;flex-wrap:wrap;justify-content:center">`+CLOCKS_G1.map(c=>`<div>${F.clock(c[1],c[2],196)}<p class="fig-label">Clock ${c[0]}</p></div>`).join("")+`</div>`}function sharesFigG1(){const st=`stroke="${INK}" stroke-width="3.4" stroke-linejoin="round"`;const W=720,H=240;let b=`<rect x="3" y="3" width="${W-6}" height="${H-6}" rx="22" fill="var(--surface)" stroke="var(--line)" stroke-width="4"/>`;b+=`<circle cx="120" cy="108" r="72" fill="${GOLDL}" ${st}/><path d="M120 36 V180" ${st} fill="none"/>`;b+=labG(120,214,"Shape A");b+=`<rect x="276" y="52" width="176" height="112" rx="6" fill="${ROSE}" ${st}/><path d="M364 52 V164 M276 108 H452" ${st} fill="none"/>`;b+=labG(364,214,"Shape B");b+=`<circle cx="600" cy="108" r="72" fill="#C9A6EC" ${st}/><path d="M558 50 L558 166" ${st} fill="none"/>`;b+=labG(600,214,"Shape C");return`<svg viewBox="0 0 ${W} ${H}" width="700" role="img" aria-label="Shape A is a circle cut by one line down the middle into two equal parts. Shape B is a rectangle cut by two lines into four equal parts. Shape C is a circle cut by one off center line into two parts that are not the same size.">${b}</svg>`}const STOPS=[{id:1,title:"Night Sound Check",short:"Sounds",parts:[{std:["RF.1.2"],n:6,dur:70,dir:"Listen to your teacher. Say the sounds and words out loud.",html:()=>`<p class="huge" aria-hidden="true">${ic(EAR,96)} ${ic(STARS,96)}</p><p class="big" style="text-align:center">Listen. Then say it.</p>`,key:["Blend these sounds: /l/ /a/ /m/ /p/ (lamp)","Blend these sounds: /s/ /t/ /ar/ (star)","Clap the word parts in lantern. How many parts? (2 parts: lan and tern)","What is the last sound in night? (/t/)","Say all the sounds in moon. (/m/ /oo/ /n/, three sounds)","Which word has a long vowel sound: light or lamp? (light)"],desc:"blending, segmenting, and isolating sounds, counting syllables, and telling long from short vowels in spoken words"}]},{id:2,title:"Lantern Hops",short:"Hops",parts:[{std:["1.OA.C.5"],dur:90,dir:"Count out loud like you are hopping from lantern to lantern. Say each answer.",html:()=>`<div class="figure">${ropeRow(5)}</div><p class="small" style="text-align:center">Each lantern on the rope is one hop.</p>`,qs:["Start at 7. Count on 6. Where do you land? What adding sentence is that?","Start at 15. Count back 3. Where do you land? What take away sentence is that?","Solve 3 + 9 by counting on. Which number is faster to start at? Say the numbers you count.","Solve 14 - 10. Start at 10 and count up to 14. How many hops is that?","True or silly? To solve 12 - 2, Tam counts 12, 11 and says the answer is 11."],key:["Counts 8, 9, 10, 11, 12, 13. Lands on 13. 7 + 6 = 13","Counts 14, 13, 12. Lands on 12. 15 - 3 = 12","Starts at 9. Counts 10, 11, 12. Answer 12","Counts 11, 12, 13, 14. That is 4 hops, so 14 - 10 = 4","Silly. The first number is not a hop. Count back two hops: 11, 10. The answer is 10"],desc:"counting on and counting back or up to add and subtract"}]},{id:3,title:"Night Words",short:"Night Words",parts:[{std:["RF.1.3"],kind:"words",words:WORDS,n:12,dur:85,dir:"Read each word out loud. The last one is a silly word. Just sound it out.",key:["Count each word read correctly. zide is a silly word: listen for the long i that the final e makes.","Watch for: ch digraph (chin), nk ending (bank), blend plus a vowel team (glow), double letters (bell), final e (home), igh (night), three-letter blend plus a vowel team (street), r-controlled ar (star), the -ed ending said as /id/ (lifted), a compound word (moonlight), two syllables with r-controlled er (river)."],desc:"reading words with digraphs, blends, final e, vowel teams, r-controlled vowels, endings, and two syllables"}]},{id:4,title:"Count the Lanterns",short:"To 120",parts:[{std:["1.NBT.A.1"],n:4,dur:85,dir:"Count and read out loud. Write your numbers on your paper and hold it up.",html:()=>`<p class="small" style="text-align:center">The town counts every lantern before it goes up on the rope.</p>`,qs:["Count out loud from 88 to 104.","Read these numbers out loud: 67, 101, 115.","Write the number one hundred twelve.","Count the lanterns in the picture. Write the number that tells how many."],fig2:()=>F.row(lanternGrid(16,8)),key:["88, 89, 90 ... 99, 100, 101, 102, 103, 104. Watch the jump past 99","Sixty-seven, one hundred one, one hundred fifteen","112, not 10012","16"],desc:"counting, reading, and writing numerals to 120 and counting objects"}]},{id:5,title:"Our Town Tonight",short:"Town Read",parts:[{std:["RF.1.4"],kind:"read",n:75,label:"words read correctly",dur:90,dir:"Look at the three pictures. Then read the story out loud in your best reading voice.",html:()=>`${F.row(F.pic(lanternSvg(52,GOLDL),"a paper lantern","3.6rem"),F.pic(HOUSE,"the main street","3.6rem"),F.pic(BRIDGE,"the bridge over the river","3.6rem"))}${story("Our Town Tonight",TOWN)}`,key:["75 words, not counting the title. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Point to the three pictures first so lantern, street, and bridge are clear before the student reads.","Note pace, expression, and whether the student rereads to fix a mistake.","Quick check after reading: What does the river do with the lanterns? (it holds them, it shows them in the water)"],desc:"a 75-word night-town story read aloud"}]},{id:6,title:"Lantern Problems",short:"Problems",parts:[{std:["1.OA.A.1"],dur:125,dir:"Listen to each story problem. You can draw on your paper. Say your answer.",html:()=>`<div class="figure">${ropeRow(7)}</div><p class="small" style="text-align:center">The town hangs its lanterns on long ropes across the street.</p>`,qs:["One rope holds 9 lanterns and the other rope holds 8. How many lanterns in all?","There were 14 lanterns lit. The wind blew out 6 of them. How many are still lit?","Tam counted 7 stars. Dev counted 15 stars. How many more stars did Dev count?","There are 18 lanterns. 9 of them are gold. The rest are red. How many are red?","Some lanterns were already on the rope. Then 5 more went up. Now there are 13. How many were on the rope at the start? Write a number sentence with a box and hold it up."],key:["17 lanterns (9 + 8 = 17)","8 lanterns (14 - 6 = 8)","8 more stars (15 - 7 = 8 or 7 + 8 = 15)","9 red (9 + 9 = 18 or 18 - 9 = 9)","8 lanterns. Writes a box plus 5 equals 13, or 13 - 5 equals a box"],desc:"addition and subtraction word problems within 20, with the unknown in different places"}]},{id:7,title:"Noor's Lantern",short:"Noor",parts:[{std:["RL.1.1"],dur:85,dir:"Read the story out loud. Then listen to each question and answer out loud.",html:()=>story("Noor's Lantern",LANTERN),qs:["What did Noor make?","What was it made of?","What was the problem at the rope?","Who helped Noor, and how?","Ask me a question about the story."],key:["A lantern","Red paper and thin sticks","The last hook on the rope was too high for her to reach","Tam. He ran over with a crate for her to stand on","Asks a real question about the story, such as: Why did she want it at the end of the rope? If stuck, say: Start with who, what, or where."],desc:"asking and answering key detail questions about a story the student read"}]},{id:8,title:"Smart Adding",short:"Smart Add",parts:[{std:["1.OA.B.3"],dur:120,dir:"Answer out loud. Tell how you know.",html:()=>`<p class="huge" style="font-size:3rem;margin:4px 0" aria-hidden="true">${lanternSvg(48,ROSE)} ${lanternSvg(48,GOLDL)} ${lanternSvg(48,"#C9A6EC")}</p>`,qs:["6 + 9 = 15. So what is 9 + 6?","Dev says 7 + 4 is easier if he turns it around and thinks 4 + 7. Is that OK? What is the total?","Add 3 + 7 + 8. Which two numbers would you add first? Why?","Add 6 + 4 + 9.","Make a ten to solve 9 + 6. Break the 6 into 1 and 5."],key:["15. Knows it without counting because the two numbers just switch places","Yes, that is fine. The order does not change the total. Both make 11","18. Adds 3 + 7 to make 10, then 10 + 8","19. Adds 6 + 4 to make 10, then 10 + 9","15. 9 + 1 = 10, then 10 + 5 = 15"],desc:"using turn-around facts and making ten as strategies to add"}]},{id:9,title:"Ropes of Ten",short:"Tens Ones",parts:[{std:["1.NBT.B.2"],n:5,dur:95,dir:"Look at the blocks. Answer out loud.",html:()=>`<p class="small" style="text-align:center">A full rope holds 10 lanterns. A long block stands for one full rope of ten, and a small cube stands for one loose lantern.</p>`,fig:()=>F.row(F.tens(3,4)),qs:["Look at the picture. How many full ropes of ten do you see, and how many loose lanterns? What number is that?","In the number 17, what does the 1 stand for? What does the 7 stand for?","The town has 80 lanterns. How many full ropes of ten is that? How many loose lanterns are left over?","Which is more, 6 ropes of ten or 50 lanterns? How do you know?","The number 14 is one ten and four ones. Say a number that is one ten and nine ones."],key:["3 ropes of ten and 4 loose. That is 34","The 1 stands for one ten, which is ten lanterns. The 7 stands for seven ones","8 ropes of ten, and 0 loose lanterns left over","6 ropes of ten. 6 tens is 60, and 60 is more than 50","19"],desc:"place value in two-digit numbers (bundles of ten and leftover ones)"}]},{id:10,title:"Add Up the Street",short:"Add Up",parts:[{std:["1.NBT.C.4"],n:5,dur:95,dir:"Solve each one on your paper. Say your answer and tell how you got it.",html:()=>`<p class="big" style="margin-top:0">The crew counts the lanterns street by street.</p>`,qs:["River Street has 23 lanterns. The crew adds 5 more. How many now?","Pine Street has 47 lanterns. The crew adds 30 more. How many now?","Bridge Street has 36 lanterns. The crew adds 8 more. How many now?","Mill Street has 52 lanterns. The crew adds 20 more. How many now?","The park has 68 lanterns. The crew adds 7 more. How many now?"],key:["28 (23 + 5 = 28. Only the ones change)","77 (47 + 30 = 77. Adding tens to tens: 4 tens and 3 tens is 7 tens)","44 (36 + 8 = 44. 6 + 8 is 14, so a new ten is made)","72 (52 + 20 = 72)","75 (68 + 7 = 75. 8 + 7 is 15, so a new ten is made)"],desc:"adding within 100 (a two-digit number plus a one-digit number and plus a multiple of ten)"}]},{id:11,title:"Take Away Tens",short:"Take Tens",parts:[{std:["1.NBT.C.6"],n:5,dur:80,dir:"Answer out loud. For the last one, tell how you know.",html:()=>`<p class="big" style="margin-top:0">Every rope that comes down takes ten lanterns off the street.</p>`,fig:()=>F.row(F.tens(7,0)),qs:["There are 70 lanterns up. Three ropes of ten come down. 70 - 30 is what?","60 - 40","90 - 20","80 - 50","40 - 10. Tell me how you know, using the word tens."],key:["40 (7 tens take away 3 tens is 4 tens)","20","70","30","30. Looks for: 4 tens take away 1 ten is 3 tens, which is 30"],desc:"subtracting multiples of ten from multiples of ten within 100"}]},{id:12,title:"Measure the Rope",short:"Measure",parts:[{std:["1.MD.A.2"],n:5,dur:95,dir:"Look at the blocks under the rope and the scarf. Answer out loud.",fig:()=>F.row(unitFig()),qs:["How many blocks long is the rope?","How many blocks long is the scarf?","Which is longer, the rope or the scarf? How many blocks longer?","Why do the blocks have to touch, with no gaps and no overlaps?","If you measured the rope with blocks that were twice as long, would you need more blocks or fewer blocks?"],key:["6 blocks","4 blocks","The rope. It is 2 blocks longer (6 - 4 = 2)","A gap or an overlap would make the count wrong. The blocks have to sit end to end so each one covers its own part of the length","Fewer blocks. Bigger units means it takes fewer of them to cover the same length"],desc:"measuring length as a whole number of same-size units laid end to end"}]},{id:13,title:"Lantern Tally",short:"Chart",parts:[{std:["1.MD.C.4"],n:5,dur:100,dir:"Look at the graph. Answer out loud.",html:()=>`<p class="big" style="margin-top:0">The crew counted the lanterns on three streets and made this graph.</p>`,fig:()=>F.row(F.barGraph({title:"Lanterns on each street",cats:["River","Pine","Bridge"],vals:[6,9,4],max:10,step:1})),qs:["How many lanterns are on Pine Street?","Which street has the fewest lanterns?","How many more lanterns are on Pine Street than on Bridge Street?","How many lanterns are on River Street and Bridge Street together?","How many lanterns are there on all three streets?"],key:["9","Bridge Street, with 4","5 more (9 - 4 = 5)","10 (6 + 4 = 10)","19 (6 + 9 + 4 = 19)"],desc:"reading a graph with three categories and answering how many more and how many in all"}]},{id:14,title:"Night Sign Check",short:"Signs",parts:[{title:"Sentence Spotter",std:["RF.1.1"],dur:50,dir:"Look at the sentences. Answer out loud.",html:()=>`<p class="passage" style="text-align:center">The lanterns glow. Can you see the river?</p>`,qs:["How many sentences do you see? How can you tell?","Read the first word of the second sentence. What kind of letter does it start with?","What is the mark at the end of the second sentence called? What does it tell you?","Spot the mistake. Look at the words in the box. What 2 things need to be fixed?"],fig2:()=>`<div class="figure"><p class="passage" style="border:3px dashed var(--line);border-radius:16px;padding:10px 26px;margin:0">the moon is up</p></div>`,key:["2 sentences. Each one starts with a capital letter and ends with an end mark","The word is Can. It starts with a capital, or uppercase, C","A question mark. It tells you the sentence asks something","The first word needs a capital letter, and the sentence needs a period at the end"],desc:"finding sentences by their first word, capital letter, and end mark"},{title:"Town Fix It",std:["L.1.1"],dur:70,dir:"Listen to your teacher read each one. Say your answer out loud.",qs:["Today we walk to the bridge. Last night we ____.","One lantern, two ____.","Which sounds right? The owl fly at night. Or: The owl flies at night.","Join these two sentences with the word <b>and</b>: The sky is dark. The stars are out.","Add a word that tells more about the lantern: The ____ lantern swings on the rope.","Finish it so it tells where: The cat sits ____ the tree."],key:["walked","lanterns","The second one. One owl goes with the verb flies","The sky is dark, and the stars are out","Any describing word that fits, such as gold, red, bright, or paper","Any word that tells where and fits, such as under, by, near, or beside"],desc:"spoken grammar items (past tense, plural nouns, subject and verb match, joining two sentences, describing words, place words)"}]},{id:15,title:"Lamplighter Radio",short:"Listen",parts:[{title:"Listen Up",std:["SL.1.2"],n:4,dur:65,read:LAMPLIGHTER,dir:"Listen carefully. Your teacher will read about a job from long ago. Then answer out loud.",html:()=>`<p class="huge" aria-hidden="true">${ic(EAR,96)}</p><p class="big" style="text-align:center">Listen.</p>`,key:["Ask: What was a lamplighter's job? (to light the oil lamps on the street corners, and to put them out again)","Ask: What did the lamplighter carry? (a long pole with a small flame on the end)","Ask: How did people know what time it was? (they watched the lamplighter go by)","Say: Ask me one question about lamplighters. (asks 1 question that is about what was read and starts with a question word, such as: How many lamps did one person light?)"],desc:"asking and answering questions about a text read aloud"},{title:"Tell Me About It",std:["SL.1.4"],n:3,label:"checks met",dur:60,dir:"Talk for about one minute. Speak clearly.",html:()=>`<p class="big">Tell me about something you can see out a window at night.</p><ul class="qlist" style="margin-top:14px"><li>What is it?</li><li>What does it look like?</li><li>How do you feel when you see it?</li></ul>`,key:["Names the thing and gives 2 or more details about it (SL.1.4)","Gives 2 or more details about what it looks like, and they stay on this one thing (SL.1.4)","Says how it makes them feel, in at least 1 complete sentence (SL.1.4)"],desc:"describing a thing with relevant details"}]},{id:16,title:"Pack the Night Walk",short:"Pack List",parts:[{std:["W.1.8"],n:3,label:"checks met",dur:80,dir:"Look at the chart. Write 1 sentence on your paper and hold it up.",html:()=>`<p class="big">The crew wants to write down every star they can see from the bridge. What will they take? Use the chart.</p>`,fig:()=>packList(),key:["Finds the answer in the chart. Your help is fine: read the two columns out loud and point to the row headings","Writes a sentence drawn from the chart, such as: They will take the small notebook","The answer fits the question. It names the one item on the list that is for writing things down"],desc:"using a provided chart to answer a question in writing"}]},{id:17,title:"Night Journal",short:"Write",parts:[{wk:"opinion",alt:{group:"write",label:"Bridge or Window",icon:"💬",hint:"Tell what you think and why"},std:["W.1.1"],n:4,label:"checks met",dur:170,dir:WDIR,html:()=>`<p class="big">Would you rather watch the night sky from the bridge over the river, or from your own window? Write what you think and tell why.</p><div class="figure">${F.pic(BRIDGE,"the bridge over the river","3.6rem")}${F.pic(HOUSE,"your own window","3.6rem")}</div>${TWO}`,key:["Names the topic: watching the night sky from the bridge or from a window (W.1.1)","States an opinion, which one the student would pick (W.1.1)","Gives at least one reason for the opinion, such as it is warmer or you can see more (W.1.1)","Gives some sense of closure, such as: That is why I would pick it (W.1.1)"],desc:"an opinion piece about where to watch the night sky"},{wk:"story",alt:{group:"write",label:"A Night I Remember",icon:"✏",hint:"Tell two things that happened, in order"},std:["W.1.3"],n:4,label:"checks met",dur:170,dir:WDIR,html:()=>`<p class="big">Write about a night you remember. Tell two things that happened, in order. Use the words first and then. End by telling how it felt.</p><div class="figure">${F.pic(MOON,"a night you remember","3.4rem")}${F.pic(STAR,"what you saw","3.4rem")}${F.pic(COCOA,"how it felt","3.4rem")}</div>${TWO}`,key:["Tells about two or more things that happened, in an order that makes sense (W.1.3)","Includes some detail about what happened, not just a list (W.1.3)","Uses a time word such as first, then, next, or after that to signal the order (W.1.3)","Ends with a sense of closure, such as how it felt or what happened last (W.1.3)"],desc:"a narrative about a night the student remembers, told in order"}]},{id:18,title:"Why Stars Look Small",short:"Star Facts",parts:[{std:["RI.1.1"],n:3,dur:70,dir:"Read the six lines out loud. Then answer out loud.",html:()=>`<div class="figure" aria-hidden="true">${ic(STARS,60)}${ic("sun",60)}</div><p class="passage" style="text-align:center">${STARS_TEXT}</p>`,qs:["Why do stars look small to us?","The text says our sun is a what?","Now you ask me a question about these lines."],key:["Because they are very far away.","A star. The text says our sun is a star too.","Asks a real question answered by or raised by the lines, such as: How hot is a star? or Why is the sun close? If the student only tells a fact, say: Make it into a question that starts with what, why, or how."],desc:"asking and answering key detail questions about an informational text the student read"}]},{id:19,title:"One True Thing",short:"Facts Write",parts:[{wk:"facts",std:["W.1.2"],n:3,label:"checks met",dur:75,dir:"Write on your paper. Then hold it up and read it to your teacher.",html:()=>`<p class="big">Pick one: the moon, a paper lantern, or an owl. Write its name. Then write one or two true things about it. Finish with one sentence that ends it.</p><div class="figure">${F.pic(MOON,"the moon","3.2rem")}${F.pic(lanternSvg(44,GOLDL),"a paper lantern","3.2rem")}${F.pic(OWL,"an owl","3.2rem")}</div>`,key:["Names the topic, the one thing the writing is about (W.1.2)","Supplies at least one true fact about it, such as: The moon is in the night sky. A lantern is made of paper. An owl is awake at night (W.1.2)","Gives some sense of closure, one sentence that ends it, such as: That is why I like the moon (W.1.2)","Two or three sentences is plenty here. Spelling is not scored. If the student tells you a fact but cannot write it, note that and count the check only for what is on the paper."],desc:"a short informative piece that names a topic, gives a fact, and closes"}]},{id:20,title:"Night Clocks and Fair Shares",short:"Clock Shares",parts:[{title:"Lantern Clock",std:["1.MD.B.3"],n:3,dur:60,dir:"Look at each clock. Say the time out loud. Write the last one on your paper.",html:()=>`<p class="big" style="margin-top:0">The clock on the bridge tells the crew when to light the ropes.</p>`,fig:()=>clockRowG1(),qs:["What time is Clock A?","What time is Clock B?","The lanterns go on at half past seven. Write that time on your paper and hold it up."],key:["6:00, said as six o'clock. The minute hand is on the 12.","8:30, said as eight thirty or half past eight. Watch for a student who says nine thirty because the hour hand has moved halfway to the 9.","7:30. Clock C is there to read too if you have time: 10:00, ten o'clock."],desc:"telling and writing time to the hour and the half hour"},{title:"Fair Shares",std:["1.G.A.3"],n:3,dur:65,dir:"Look at the three shapes. Answer out loud.",fig:()=>F.row(sharesFigG1()),qs:["Shape A is cut into 2 equal parts. What do we call one of those parts?","Shape B is cut into 4 equal parts. What do we call one of those parts, and how many of them make the whole rectangle?","Shape C is cut into 2 parts. Are those parts halves? How do you know?"],key:["A half, or one half. Two halves make the whole circle.","A fourth, or a quarter. 4 of them make the whole rectangle.","No. The line is not down the middle, so the two parts are not the same size. Halves have to be two equal parts."],desc:"halves and fourths of circles and rectangles, and knowing that equal shares must be the same size"}]},{id:21,title:"Copy an Owl Feather",short:"Copy a Part",parts:[{std:["1-LS1-1"],n:3,dur:90,dir:"Look at the pictures. Answer the first out loud. Draw the second on your paper and hold it up.",desc:"naming the job an animal body part does, then designing a tool that copies it to solve a human problem",html:()=>`<p class="big">An owl flies almost without a sound. Each wing feather has a front edge. It is not smooth. It is split into a soft fringe. The fringe breaks up the rushing air.</p>
     <div class="figure">${ic("owl",104)}${ic("leaf",88)}</div>
     <p class="big">The meeting house has a hall door. It bangs every time. Somebody goes out and it bangs. Everybody inside jumps.</p>`,qs:["How does a soft fringe on the edge of a feather make an owl's flight quiet?","Draw something for the door that copies the owl's soft fringed feather edge.","Tell me which animal part you copied and how your design makes the door quieter."],key:["It breaks up the rushing air instead of letting it slap against a hard edge, so there is much less noise. Any answer about softening or breaking up the air or the sound counts.","Any soft edging: a strip of felt or cloth along the door frame, a soft pad where the door meets the frame, a brush along the bottom. A hard block is partial, so ask what the owl's feather edge is like.","Needs both halves: names the soft fringed edge of the feather as the part copied, and says a soft edge meeting a hard one makes far less noise than two hard edges meeting."]}]},{id:22,title:"Owl Parents",short:"Parents",parts:[{std:["1-LS1-2"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"finding a pattern in what a parent animal does and what the young do in answer, and saying how it helps the young",read:"An owl keeps its nest in a hollow in the big tree by the lamp post. The two young owls cannot fly yet. All through the dark hours the parent goes out and comes back, and each time it lands on the branch outside the hollow it gives one low hoot. The young answer with a thin hiss, and the parent follows the hiss to the hollow and feeds them. In between, the young stay deep inside the hollow and make no sound at all.",qs:["What does the parent owl do every single time it lands on the branch?","What do the young owls do when they hear the low hoot?","How does staying quiet and deep inside the hollow in between help young owls that cannot fly?"],key:["It gives one low hoot. Every time is what makes it a pattern.","They answer with a thin hiss, which tells the parent where they are.","Nothing can find them by sound or by sight while they are tucked inside, and they cannot fall out of the tree. Any sensible answer about staying hidden and staying put counts."]},{std:["1-LS3-1"],n:3,dur:75,dir:"Look at the pictures. Answer out loud.",desc:"making observations that young plants and animals are like their parents but not exactly like them",html:()=>`<p class="big">A new shoot coming up from a bulb. The grown plant it will become. A young owl and the owl that is its parent.</p>
     <div class="figure">${ic("sprout",92)}${ic("tulip",104)}</div>
     <div class="figure">${ic("owl",88)}${ic("owl",116)}</div>`,qs:["Name one way the new shoot is like the grown plant.","Name one way the new shoot is not exactly like the grown plant.","The young owl is smaller and fluffier than the parent, but its eyes, beak and claws are the same shape. What does that tell you about young animals and their parents?"],key:["Both are green, both come up out of the same bulb, both have a stem. Any likeness counts.","The shoot is much shorter, it has no flower, its leaves are not open yet. Any difference counts.","Young animals are like their parents in the big ways but not exactly like them in every way. The shape stays, the size and the fluff change."]}]},{id:23,title:"Stars That Come Back",short:"Sky Patterns",parts:[{std:["1-ESS1-1"],n:4,dur:90,dir:"Look at the chart. Answer out loud.",desc:"finding a pattern in sky observations made across a year and using it to predict what comes next",html:()=>`<p class="big">The lamplighter writes down which group of bright stars is overhead at nine at night.</p>
     <table class="bigTable"><tr><th>Time of year</th><th>Which star group was overhead</th></tr>
     <tr><td>last winter</td><td>the hunter</td></tr>
     <tr><td>last summer</td><td>the swan</td></tr>
     <tr><td>this winter</td><td>the hunter</td></tr></table>
     <div class="figure">${ic("star",84)}${ic("lantern",84)}${ic("moon",84)}</div>`,qs:["Which star group was overhead last winter?","Which star group was overhead last summer?","Next summer, which group do you predict will be overhead, and how do you know?","The moon is up tonight and it will be up again tomorrow night. Are the things we see in the sky a jumble, or do they follow patterns we can count on?"],key:["the hunter","the swan","the swan. The same groups come back at the same time of year, which is a pattern that repeats, so you can predict it.","They follow patterns. The sun, the moon and the stars do the same things over and over, and that is why they can be predicted."]},{std:["1-ESS1-2"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"relating the number of hours of daylight to the time of year from observations made across a year",html:()=>`<p class="big">The lamplighter wrote down how many hours the street lamps had to be lit.</p>
     <table class="bigTable"><tr><th>Month</th><th>Hours of daylight</th><th>Hours the lamps burned</th></tr>
     <tr><td>January</td><td>10</td><td>14</td></tr>
     <tr><td>July</td><td>15</td><td>9</td></tr></table>`,qs:["Which month had more hours of daylight?","In which month did the lamps have to burn longer?","Why do more hours of daylight mean fewer hours of lamp light? Use the chart to say how you know."],key:["July, 15 hours","January, 14 hours of lamp light","A day is the same length all year, so hours of daylight and hours of darkness trade off. July had 15 hours of daylight and only 9 of lamp light. January had 10 of daylight and 14 of lamp light."]}]},{id:24,title:"Sound in the Hall",short:"Sound",parts:[{std:["1-PS4-1"],n:4,dur:90,dir:"If you have a glass of water and a spoon, try the first part. Either way, answer out loud.",desc:"planning an investigation showing that a shaking material makes sound and that a sound can make a material shake",html:()=>`<p class="big">Fill a glass halfway with water. Tap the side of the glass with a spoon and watch the top of the water.</p>
     <div class="figure">${ic("milk",96)}${ic("balloons",96)}</div>
     <p class="big">Now stretch a balloon over the open mouth of a jar and tape it down. Put a grain of rice on top and hum loudly, close to it.</p>`,qs:["When you tap the glass and hear the ring, what happens to the top of the water?","Hold the side of the glass with your hand while it is ringing. What happens to the sound, and why?","What does the grain of rice on the balloon do while you hum?","Your voice never touched the rice. What does its hopping tell you about sound?"],key:["Little ripples run across it. The glass is shaking, and the shaking passes into the water.","The ring stops, because your hand stops the glass shaking. No shaking, no sound.","It hops or jiggles on the stretched balloon.","A sound can make a thing shake without touching it. Your humming shook the air, the air shook the balloon, and the shaking balloon tossed the rice."]}]},{id:25,title:"The Dark Hallway",short:"Light",parts:[{std:["1-PS4-2"],n:3,dur:75,dir:"Answer out loud.",desc:"accounting for why an object in darkness can be seen only when light shines on it",html:()=>`<p class="big">The hallway of the meeting house has no window. Late at night, with the lamp out, it is completely dark.</p>
     <div class="figure">${ic("key",96)}${ic("lamp",96)}</div>`,qs:["A silver key is hanging on a hook in that hallway. Can you see it in the dark? Say why or why not.","What has to happen before you can see it?","Silver is shiny. Does being shiny help in a hallway with no light at all? Say why."],key:["No. No light reaches the key, and a thing can only be seen when light shines on it and comes back to your eyes.","Light has to reach it: a lamp lit, a flashlight, or a door opened to let light in.","No. Shiny things look bright because they bounce back a lot of light. With no light to bounce, a shiny thing is as invisible as a dull one."]},{std:["1-PS4-3"],n:4,dur:90,dir:"Look at the test results. Answer out loud.",desc:"using test results to tell what happens when different materials are put in the path of a beam of light",html:()=>`<p class="big">One lamp beam was pointed at four things in the hallway and what it did was written down.</p>
     <table class="bigTable"><tr><th>What was put in the beam</th><th>What the beam did</th></tr>
     <tr><td>a clean window pane</td><td>went straight through</td></tr>
     <tr><td>a paper lantern shade</td><td>came through softened and spread out</td></tr>
     <tr><td>the closed wooden door</td><td>stopped, and made a dark shadow</td></tr>
     <tr><td>the hall mirror</td><td>bounced back across the hall</td></tr></table>`,qs:["Which thing let the light through without changing it?","Which thing let the light through but spread it out and softened it?","Why do people put a paper shade round a lamp instead of leaving the bulb bare? Use the chart in your answer.","You want to light the far end of the hall from where you are standing. Which of the four would help, and how?"],key:["the clean window pane","the paper lantern shade","Because the shade spreads the light out and softens it, so it is not harsh to look at. The chart shows paper does that to a beam.","the hall mirror, because it bounces the beam back across the hall and can send it down to the far end."]}]},{id:26,title:"Across the Square",short:"Signals",parts:[{std:["1-PS4-4"],n:3,dur:90,dir:"Draw your answer on your paper. Then answer out loud.",desc:"designing a device that uses light or sound to send a message over a distance too far to shout",html:()=>`<p class="big">The town square is wide, and the houses on the far street cannot hear anyone calling from the middle of it.</p>
     <div class="figure">${ic("clock",88)}${ic("lantern",88)}${ic("megaphone",88)}</div>`,qs:["Draw a device in the square that tells the far street that the meeting is about to begin. It has to use light or sound.","What is your device called, and is it a light signal or a sound signal?","Some people in the town cannot hear well. What could you add so that the message reaches them too?"],key:["Any device that carries light or sound across the square: a bell in the tower, a horn, a drum, a bright lamp hoisted on a pole, a lamp flashed on and off.","Names it and says which one it uses.","A light signal alongside the sound: a lamp lit in the tower, a flashing light, a bright flag raised in daylight. The idea to listen for is sending the same message two ways."]}]},{id:27,title:"Fix the Falling List",short:"Fix It",parts:[{std:["K-2-ETS1-1"],n:3,dur:75,dir:"Listen while your teacher reads. Then answer out loud.",desc:"naming a problem people want to change, asking a question about it, and saying what to observe first",read:"At the start of the new term the class wrote its jobs for the week on a big sheet of paper and stuck it to the wall by the door. By the second day the bottom corners had curled up and nobody could read the last two jobs. By the fourth day the whole sheet was on the floor.",qs:["What is the problem the class wants to change?","What question would you ask first if you wanted to fix this?","Before you make a fix, what would you keep an eye on for a few days?"],key:["The paper list curls up and falls off the wall, so the jobs on it cannot be read.","Any real question: what is sticking it up, how big is the sheet, is the wall rough or smooth, does the door make a draught, how heavy is the paper. A statement is not a question, so ask once more.","Any real observation: count how many days it stays up, watch which corner curls first, notice whether it falls when the door opens, feel whether the wall is dusty."]},{std:["K-2-ETS1-2"],n:3,dur:90,dir:"Draw your answer on your paper and hold it up. Then answer out loud.",desc:"making a simple drawing of a fix and explaining how the shape of the object makes it work",html:()=>`<p class="big">Draw something that keeps the list flat on the wall all week.</p>
     <div class="figure">${ic("board",88)}${ic("books",88)}${ic("pencil",88)}</div>`,qs:["Draw your fix on the wall with the list.","Point to the part that holds the paper and tell me its shape.","Tell me why that shape holds better than one piece of tape in the middle of the sheet."],key:["Any real fix: clips along the top, a stiff board behind the paper, a frame round the edge, a rod across the bottom, pins at all four corners, a pocket the sheet slides into.","Names a shape: a long bar across the top, a square frame, a flat stiff board, a narrow slot.","Because the shape holds the whole edge or the whole sheet instead of one small spot. Tape in the middle leaves every corner free to curl."]}]},{id:28,title:"Which Holder Worked",short:"Test Data",parts:[{std:["K-2-ETS1-3"],n:3,dur:75,dir:"Look at the chart. Answer out loud.",desc:"comparing the data from tests of two objects built to solve the same problem",html:()=>`<p class="big">Two holders were tested on the same wall for ten days each.</p>
     <table class="bigTable"><tr><th>Holder</th><th>Days the list fell down, out of 10</th></tr>
     <tr><td>a clip bar across the top</td><td>0</td></tr>
     <tr><td>tape at two corners</td><td>5</td></tr></table>`,qs:["Which of the two held the list better?","Tell me the numbers you used to decide.","Someone says the tape is better because it was quicker to put up. Does being quicker mean it held the list better? Say why or why not."],key:["the clip bar across the top","The list never fell with the clip bar, 0 days out of 10, and it fell on 5 days out of 10 with the tape. The numbers have to be in the answer.","No. Being quick to put up is a different question from holding the list. The test counted days the list fell, and the clip bar won that test."]}]},{id:29,title:"Rules for a Fresh Start",short:"Rights",parts:[{std:["HSS-1.1"],n:4,dur:90,dir:"Listen while your teacher reads. Then answer out loud.",desc:"telling a right from a responsibility and explaining why a group writes rules together",read:"On the first morning of the new term the class made its own list of rules. Every child said one idea out loud and the teacher wrote them all on the board. Then they voted. Three rules got the most hands. Everyone gets a turn to speak. Everyone looks after the books. Nobody goes out of the room without telling an adult.",qs:["Everyone got a turn to say an idea. Is getting a turn a right or a responsibility?","Looking after the books is something each person does. Is that a right or a responsibility?","Why would a class make its rules together instead of one person making them alone?","What should happen when somebody breaks a rule the whole class agreed to?"],key:["a right","a responsibility","Because then everyone has had a say, everyone knows what the rules are, and people keep rules better when they helped choose them.","Something fair that fixes it: the rule is explained again, the person puts right what they did, the class talks it over. Not something that frightens or shames a child. Listen for a sensible and kind answer."]}]},{id:30,title:"The Town Square Map",short:"Map Grid",parts:[{std:["HSS-1.2"],n:4,dur:90,dir:"Look at the map grid. Answer out loud.",desc:"giving an exact grid location, describing a relative location, and telling a physical feature from a built one",html:()=>`<p class="big">A map of the town square, drawn on a grid.</p>
     <table class="bigTable"><tr><th></th><th>1</th><th>2</th><th>3</th></tr>
     <tr><th>A</th><td>${ic("cabin",56)}</td><td>${ic("clock",56)}</td><td>${ic("cabin",56)}</td></tr>
     <tr><th>B</th><td></td><td>${ic("tree",56)}</td><td></td></tr>
     <tr><th>C</th><td>${ic("bridge",56)}</td><td></td><td>${ic("drop",56)}</td></tr></table>
     <p class="big">${ic("cabin",48)} shops &nbsp; ${ic("clock",48)} the clock tower &nbsp; ${ic("tree",48)} the old elm &nbsp; ${ic("bridge",48)} the stone bridge &nbsp; ${ic("drop",48)} the river</p>`,qs:["Find the clock tower. Give its exact spot on the grid, the letter and the number.","Where is the old elm compared to the clock tower? Use words like above, below, left of, or right of.","Point to something nature made and something people made on this map.","Someone standing at the stone bridge wants to reach a shop at A3. Name the squares they would cross on the way."],key:["A2. Both parts are needed.","Below the clock tower, in the same column.","Needs both halves. Nature: the old elm, the river. Built: the shops, the clock tower, the stone bridge.","Any sensible path across the grid, for example C1 to B1 to A1 to A2 to A3, or C1 to B2 to A3. The point is a path that moves square by square, not a leap."]},{std:["HSS-1.5"],n:3,dur:75,dir:"Answer out loud.",desc:"naming built features of a familiar place and recognizing that people in one place come from many different places",html:()=>`<p class="big">This town has a first street. There are eleven houses on it. Families live in them. They came from eight different places. Four different languages are spoken there. All of them are on one street. Three of those families moved here. They came from another country. A person may be moving away. They leave one country. They go to live in another. That person is called an immigrant.</p>
     <div class="figure">${ic("cabin",88)}${ic("books",88)}${ic("globe",88)}</div>`,qs:["Do the people on one street all come from the same place? Say how you know from the story.","Think of your own street or block. Name three things on it that people built.","A person may be moving away. They leave one country. They go to live in another. That person is called an immigrant. Name one thing an immigrant family could teach their new neighbors, and one thing the neighbors could teach them."],key:["No. Eleven families came from eight different places and four languages are spoken there.","Any three built things: houses, a sidewalk, a mailbox, a fence, a lamp post, a road, a shop.","Needs both halves. The immigrant family could teach a word from their language, a food, a game, a song, a dance, a custom from where they came from. The neighbors could teach them where the shops are, which bus to take, who lives nearby, the rules of the park. The word immigrant used correctly is the part to listen for. (HSS-1.5)"]}]},{id:31,title:"Symbols, Then and Now",short:"Symbols",parts:[{std:["HSS-1.3"],n:3,dur:75,dir:"Answer out loud.",desc:"recognizing national symbols in everyday places and naming a building that stands for the country's government",html:()=>`<p class="big">Look at a coin or a one dollar bill and you will find an eagle on it. The eagle is a symbol. It stands for the United States. So is the White House. The president of the country lives there. The president works there too.</p>
     <p class="big">The country has one more important paper. It is called the Constitution. It is a written set of rules. The rules are for the whole country. It is the reason for a president. There is a president because of it.</p>
     <div class="figure">${ic("coin",96)}${ic("eagle",96)}</div>`,qs:["Where in your own pocket or purse could you find a symbol of the United States?","What is the White House, and why is a building put on stamps and coins instead of just being a place where somebody lives?","The country has a written set of rules for everybody. What is that paper called, and name one thing it does."],key:["On a coin or on a dollar bill. Accept naming the eagle on a coin.","It is where the president lives and works. It is on stamps and coins because it stands for the country's government, not just for one person's house.","The Constitution. It is a written set of rules. The rules are for the whole country. Any true second part: it is why there is a president, it says how the government works, it sets out rules everybody has to keep. (HSS-1.3)"]},{std:["HSS-1.4"],n:4,dur:90,dir:"Look at the chart. Answer out loud.",desc:"comparing everyday life long ago with life today and telling what changed from what stayed the same",html:()=>`<p class="big">Washing the clothes.</p>
     <table class="bigTable"><tr><th></th><th>Long ago</th><th>Today</th></tr>
     <tr><td>how they were washed</td><td>rubbed by hand on a ridged board</td><td>turned by a machine</td></tr>
     <tr><td>how they were dried</td><td>hung on a line outdoors</td><td>a machine, or a line outdoors</td></tr>
     <tr><td>how long it took</td><td>most of a day</td><td>about an hour</td></tr>
     <tr><td>school in this town</td><td>one room, every age together, one teacher, slates to write on</td><td>a room for each grade, many teachers, paper and screens</td></tr></table>
     <div class="figure">${ic("drop",88)}${ic("scarf",88)}</div>`,qs:["Long ago, how did people get the clothes clean?","How are clothes washed today?","Look at the school row. Name two ways school in this town was different long ago. Then say who in your own family you could ask about school when they were small.","Look at the drying row. Name one thing people still do today exactly the way they did long ago."],key:["Rubbed by hand on a ridged board.","Turned by a machine.","Any two from the school row: one room instead of a room for each grade, every age together, only one teacher, writing on slates instead of paper. For the second part, any real person: a parent, a grandparent, an aunt or uncle, an older neighbor. Asking an older person is called an oral history, and it is one of the sources this standard names. (HSS-1.4)","Hanging clothes on a line outdoors. Plenty of people still do that, so this row shows something that stayed."]}]}];const LEVELUPS={3:{id:"L3",lv:true,title:"Level Up: Longer Words",std:["RF.2.3"],needs:["RF.1.3"],n:3,dir:"Read each word out loud.",html:()=>`<div style="text-align:center">${["midnight","unlit","brightest"].map(w=>`<p class="huge" style="font-size:clamp(2.6rem,9vw,5rem);margin:14px 0">${w}</p>`).join("")}</div>`,key:["midnight (two syllables, compound word, igh in the second part)","unlit (prefix un-)","brightest (suffix -est on a word with igh)"]},5:{id:"L5",lv:true,title:"Level Up: The Lantern Crew",std:["RF.2.4"],needs:["RF.1.4"],n:60,label:"words read correctly",dir:"Read this harder story out loud in your best reading voice.",html:()=>`<p class="passage">${CREW}</p>`,key:["60 words. Mark each word read wrong or skipped. A word the student fixes alone counts as correct.","Note pace and expression. A grade 2 reader should group the words into phrases, not read one word at a time.","Quick check after reading: Why does the crew measure as they go? (so no lantern hangs lower than the rest and the rope does not look crooked)"]},6:{id:"L6",lv:true,title:"Level Up: Two-Step Problem",std:["2.OA.A.1"],needs:["1.OA.A.1"],n:1,dir:"Solve on your paper. Tell your teacher the answer.",html:()=>`<p class="big">The crew had 34 lanterns on the cart. A truck brought 28 more. Then the crew hung 19 of them on the rope. How many lanterns are still on the cart?</p>`,key:["43 lanterns (34 + 28 = 62, then 62 - 19 = 43)"]},7:{id:"L7",lv:true,title:"Level Up: Why and How",std:["RL.2.1"],needs:["RL.1.1"],n:2,dir:"Answer out loud. Use the story.",html:()=>`<p class="passage" style="font-size:1.5rem">${LANTERN}</p><ol class="qlist"><li>Why could Noor not hang her lantern at first?</li><li>How did Tam solve the problem?</li></ol>`,key:["The last hook on the rope was too high for her to reach","He brought a crate over so she could stand on it and reach the hook"]},10:{id:"L10",lv:true,title:"Level Up: Add It Both Ways",std:["2.NBT.B.5"],needs:["1.NBT.C.4"],n:3,dir:"Solve each one on your paper. Show your work and hold it up.",html:()=>`<ol class="qlist"><li>45 + 37</li><li>63 - 28</li><li>58 + 26</li></ol>`,key:["82 (45 + 37 = 82)","35 (63 - 28 = 35)","84 (58 + 26 = 84)"]}};const PASSAGE_STD=["RL.1.1","RL.2.1","RI.1.1","1-LS1-1","1-LS1-2","1-LS3-1","1-ESS1-1","1-ESS1-2","1-PS4-1","1-PS4-2","1-PS4-3","1-PS4-4","K-2-ETS1-1","K-2-ETS1-2","K-2-ETS1-3","HSS-1.1","HSS-1.2","HSS-1.3","HSS-1.4","HSS-1.5"];let nlOn={},tfOn={},c120On={};function nlHtml(){const marks=Object.keys(nlOn).filter(k=>nlOn[k]).map(Number);return F.numberLine({min:0,max:20,step:1,labelEvery:1,width:680,marks,clickable:true,fluid:true})+`<p class="small">Click a number to mark it. Click it again to clear.</p>`}function tfHtml(){return`<div class="tf-wrap">`+[0,1].map(f=>{let c=`<div class="tf">`;for(let i=0;i<10;i++){const k=f*10+i;c+=`<button data-k="${k}" class="c${tfOn[k]||0}" aria-label="Box ${k+1}"><span></span></button>`}return c+"</div>"}).join("")+`</div><p class="small">Click a box to add a red counter. Click again for yellow. Click again to clear.</p>`}function c120Html(){let h=`<div class="tool-scroll"><table class="c120">`;for(let r=0;r<12;r++){h+="<tr>";for(let c=1;c<=10;c++){const n=r*10+c;h+=`<td data-n="${n}" class="${c120On[n]?"on":""}">${n}</td>`}h+="</tr>"}return h+`</table></div><p class="small">Click a number to mark it. Click it again to clear.</p>`}const STARTERS={opinion:["I would pick ____.","One reason is ____.","It would be ____.","That is why I would pick it."],facts:["This is about ____.","It is ____.","One true thing is ____.","That is what I know about ____."],story:["One night, ____.","First, ____.","Then, ____.","It felt ____."]};const SENTSET={"W.1.1":"opinion","W.1.2":"facts","W.1.3":"story","W.1.8":"facts"};const SENTLAB={opinion:"If you are writing what you think:",facts:"If you are writing facts:",story:"If you are telling a story:"};function sentHtml(st){const parts=st&&st.parts&&st.parts.length?st.parts:st?[st]:[];const sets=[];parts.forEach(p=>(p.std||[]).forEach(c=>{const k=SENTSET[c];if(k&&STARTERS[k]&&sets.indexOf(k)<0)sets.push(k)}));if(!sets.length){const k=parts[0]&&parts[0].wk;sets.push(STARTERS[k]?k:"opinion")}return sets.map(k=>(sets.length>1?`<p class="small">${SENTLAB[k]}</p>`:"")+`<ul class="starters">${STARTERS[k].map(x=>`<li>${x}</li>`).join("")}</ul>`).join("")}let tpsBlk=[0,0];function tpsBlkHtml(){return`<div class="blk-row"><button class="chip" data-tb="0" data-td="1">Add a ten</button><button class="chip" data-tb="0" data-td="-1">Take a ten</button><button class="chip" data-tb="1" data-td="1">Add a one</button><button class="chip" data-tb="1" data-td="-1">Take a one</button><button class="chip" data-tb="x">Clear</button></div><div class="tool-scroll" style="text-align:center">${tpsBlk[0]+tpsBlk[1]?F.tens(tpsBlk[0],tpsBlk[1]):`<p class="small">No blocks yet.</p>`}</div><p class="small">${tpsBlk[0]} tens and ${tpsBlk[1]} ones on the mat.</p>`}function tpsBlkBind(b,r){b.querySelectorAll("[data-tb]").forEach(x=>x.onclick=()=>{if(x.dataset.tb==="x")tpsBlk=[0,0];else{const i=+x.dataset.tb;tpsBlk[i]=Math.max(0,Math.min(i?19:9,tpsBlk[i]+ +x.dataset.td))}r()})}F.clockLab=(h,m)=>{const cx=190,cy=190,R=150,pad=n=>String(n).padStart(2,"0");let s=`<svg viewBox="0 0 380 380" width="360" style="max-width:100%;height:auto" role="img" aria-label="Clock face with the hour hand and the minute hand labeled, showing ${h}:${pad(m)}">`;s+=`<circle cx="${cx}" cy="${cy}" r="${R+8}" fill="#F3DCC4" stroke="var(--fig-ink)" stroke-width="4"/><circle cx="${cx}" cy="${cy}" r="${R}" fill="var(--surface)" stroke="var(--fig-ink)" stroke-width="3"/>`;for(let i=0;i<60;i++){const a=i*Math.PI/30,l=i%5?6:13;s+=`<line x1="${cx+Math.sin(a)*(R-3)}" y1="${cy-Math.cos(a)*(R-3)}" x2="${cx+Math.sin(a)*(R-3-l)}" y2="${cy-Math.cos(a)*(R-3-l)}" stroke="var(--ink)" stroke-width="${i%5?1.3:2.6}"/>`}for(let i=1;i<=12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*108}" y="${cy-Math.cos(a)*108}" font-size="30" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink)" text-anchor="middle" dominant-baseline="central">${i}</text>`}for(let i=0;i<12;i++){const a=i*Math.PI/6;s+=`<text x="${cx+Math.sin(a)*(R+23)}" y="${cy-Math.cos(a)*(R+23)}" font-size="16" font-family="Andika,sans-serif" font-weight="700" fill="var(--sea)" text-anchor="middle" dominant-baseline="central">${i*5}</text>`}const ha=(h%12+m/60)*Math.PI/6,ma=m*Math.PI/30,hl=66,ml=90;s+=`<line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ha)*hl}" y2="${cy-Math.cos(ha)*hl}" stroke="var(--ink)" stroke-width="11" stroke-linecap="round"/><line x1="${cx}" y1="${cy}" x2="${cx+Math.sin(ma)*ml}" y2="${cy-Math.cos(ma)*ml}" stroke="var(--sea)" stroke-width="6" stroke-linecap="round"/><circle cx="${cx}" cy="${cy}" r="8" fill="var(--ink)"/>`;const tag=(ang,r,txt,col)=>{let d=ang*180/Math.PI-90;if(d>90||d<-90)d+=180;const x=cx+Math.sin(ang)*r,y=cy-Math.cos(ang)*r;return`<text transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${d.toFixed(1)})" y="-12" font-size="14" font-weight="700" font-family="Andika,sans-serif" fill="${col}" stroke="var(--surface)" stroke-width="3" paint-order="stroke" text-anchor="middle" dominant-baseline="central">${txt}</text>`};s+=tag(ha,38,"hour hand","var(--ink)")+tag(ma,51,"minute hand","var(--sea)");return s+`</svg>`};function tpsClockHtml(){return F.row([F.clockLab(3,0),"3:00, three o'clock"],[F.clockLab(7,30),"7:30, half past seven"])+`<ul class="frames"><li><b>Short hand = hours.</b> Read the big numbers, 1 to 12.</li><li><b>Long hand = minutes.</b> Read the small numbers around the edge. They count by 5s.</li></ul>`+F.table(["Where the long hand points","Minutes","How to write it and say it"],[["straight up at the 12","0 minutes","3:00, three o'clock"],["straight down at the 6","30 minutes","7:30, seven thirty or half past seven"]])+`<ul class="frames"><li>The short hand is the hour. The long hand is the minutes.</li><li>At half past, the short hand sits between two numbers. Say the smaller number.</li></ul>`}function tpsRulerHtml(){return `<div style="text-align:center"><img alt="An inch ruler from 0 to 6 with a pencil lined up at 0. The tip of the pencil is at 5 inches." src="data:image/webp;base64,${window.TP_IMG1.wp3.inchruler}" style="width:640px;max-width:100%;height:auto"></div>`+F.table(["Rule","Why it matters"],[["Start at the 0 end","the first unit has to begin where the object begins"],["The units touch, with no gaps","a gap makes the count too small"],["The units do not overlap","an overlap makes the count too big"],["Every unit is the same size","units of different sizes cannot be counted together"]])+`<p class="small">Count the spaces between the marks, not the marks themselves. The pencil above ends at the 5, so it is 5 units long.</p>`}function tpsLetterHtml(){return F.table(["Pattern","What it does","Words"],[["sh, ch, th, wh, ck","two letters, one sound","shop, chin, that, when, duck"],["bl, fl, st, sw, cr","two sounds said close together","flag, stop, swim, crab"],["a_e, i_e, o_e, u_e","the e at the end makes the vowel say its name","cave, bike, note, cube"],["ai, ay, ea, ee, oa, ow","a vowel team: two letters, one vowel sound","rain, day, seal, deep, boat, snow"],["ar, er, ir, or, ur","the r changes the vowel","barn, her, bird, corn, fur"],["-s, -ed, -ing","an ending added to a word","jumps, jumped, jumping"]])+`<ul class="frames"><li>Say each sound, then blend them together. /f/ /l/ /a/ /g/ is flag.</li><li>A long vowel says its name. A short vowel does not.</li><li>Clap the parts: snow-flake is two parts.</li></ul>`}function tpsRetellHtml(){return F.table(["Part","What to tell","Starter"],[["1. First","who it is about and where they are","First, ____."],["2. Next","what happened in the middle","Next, ____."],["3. Last","how it ended and how you felt","Last, ____."]])+`<ul class="frames"><li>Keep the parts in the order they happened.</li><li>Use the names from the story, not he or she on its own.</li></ul>`}function tpsQwordHtml(){return F.table(["Question word","What it asks about","A question you could ask"],[["Who","a person or an animal","Who helped?"],["What","a thing, or what happened","What did she find?"],["Where","a place","Where did they go?"],["When","a time","When did it start?"],["Why","a reason","Why did it happen?"],["How","the way something is done","How did they fix it?"]])+`<p class="small">Start with one of these words. A question ends with a question mark, and your voice goes up at the end.</p>`}let tpsMaskIdx=0;function tpsMaskLines(){const el=document.querySelector("#stopView .passage");if(!el)return null;const d=document.createElement("div");d.innerHTML=el.innerHTML.replace(/<br\s*\/?>/gi,"\n");const flat=(d.textContent||"").replace(/[ \t]+/g," ");let out=flat.split("\n").map(s=>s.trim()).filter(Boolean);if(out.length<2)out=flat.split(/(?<=[.!?\u201D])\s+/).map(s=>s.trim()).filter(Boolean);return out.length?out:null}function tpsMaskHtml(){const L=tpsMaskLines();if(!L)return`<p class="small">This stop has no passage on the screen to window. Lay a card under the line the student is reading and slide it down one line at a time.</p>`;if(tpsMaskIdx>=L.length)tpsMaskIdx=L.length-1;return`<div class="row center"><button class="chip" data-m="-1">Back</button><button class="chip" data-m="1">Next</button><button class="chip" data-m="0">Start over</button></div><p style="font-family:var(--font-display);font-size:clamp(1.3rem,3.2vw,2rem);line-height:1.6;text-align:center;margin:12px 0">${F.esc(L[tpsMaskIdx])}</p><p class="small">Line ${tpsMaskIdx+1} of ${L.length}. The whole passage stays on the student page. This window is for a student who loses their place, and it reads the first passage on the stop.</p>`}function tpsMaskBind(b,r){b.querySelectorAll("[data-m]").forEach(x=>x.onclick=()=>{const n=(tpsMaskLines()||[""]).length,d=+x.dataset.m;tpsMaskIdx=d?Math.max(0,Math.min(n-1,tpsMaskIdx+d)):0;r()})}const TOOLS={nl:{name:"Number line to 20",std:["1.MD.A.2","1.MD.B.3","1.MD.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.MD.A.1"],html:nlHtml,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{nlOn[x.dataset.n]=!nlOn[x.dataset.n];r()})},tf:{name:"Ten frames",std:["1.NBT.B.2","1.NBT.C.4","1.OA.A.1","1.OA.B.3","1.OA.C.5","2.NBT.A.1"],html:tfHtml,bind:(b,r)=>b.querySelectorAll("[data-k]").forEach(x=>x.onclick=()=>{tfOn[x.dataset.k]=((tfOn[x.dataset.k]||0)+1)%3;r()})},chart:{name:"120 chart",std:["1.NBT.A.1","1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","1.OA.C.5","2.NBT.A.1","2.NBT.B.5","2.OA.A.1"],html:c120Html,bind:(b,r)=>b.querySelectorAll("[data-n]").forEach(x=>x.onclick=()=>{c120On[x.dataset.n]=!c120On[x.dataset.n];r()})},sent:{name:"Sentence starters",std:["W.1.1","W.1.2","W.1.3","W.1.8"],html:sentHtml},blocks:{name:"Tens and ones blocks",std:["1.NBT.B.2","1.NBT.C.4","1.NBT.C.6","2.NBT.B.5","2.OA.A.1"],html:tpsBlkHtml,bind:tpsBlkBind},clock:{name:"Clock face card",std:["1.MD.B.3","2.MD.C.7"],html:tpsClockHtml},ruler:{name:"Inch ruler card",std:["1.MD.A.2","2.MD.A.1"],html:tpsRulerHtml},letters:{name:"Letter and sound card",std:["RF.1.2","RF.1.3"],html:tpsLetterHtml},retell:{name:"First, next, last card",std:["RL.1.1","SL.1.4","W.1.3"],html:tpsRetellHtml},qwords:{name:"Question word card",std:["K-2-ETS1-1","L.1.1","RI.1.1","RL.1.1","SL.1.2"],html:tpsQwordHtml},mask:{name:"Reading window (one line at a time)",std:["RF.1.4"],html:tpsMaskHtml,bind:tpsMaskBind}};const SUP_CAVEATS=[{t:"nl",std:["1.OA.C.5"],msg:"1.OA.C.5 is about counting on and back. With the number line, this stop shows the student can do it with a visual, not in their head."},{t:"nl",std:["1.OA.B.3"],msg:"1.OA.B.3 is about using number tricks (turn-around facts, making ten). If the student counts every hop on the number line, the stop shows counting, not the strategy."},{t:"chart",std:["1.NBT.A.1"],msg:"The 120 chart shows the numerals, so counting, reading, and writing numbers with it open is supported, not independent."},{t:"chart",std:["1.NBT.C.4","1.NBT.C.6"],msg:"On the 120 chart a student can hop down a column to add or take away a ten. Note whether the answer came from the chart or from knowing the tens."},{t:"tf",std:["1.NBT.B.2"],msg:"Ten frames show the bundles of ten for the student. Note it if the tens and ones were read off the frames rather than said from the number."},{t:"sent",msg:"Sentence starters supply the opening, the time words, and the closing, so count those checks as supported, not independent."},{t:"passage",msg:"If the passage was read to the student, this stop shows listening comprehension, not reading."},{t:"scribe",std:["W.1.1","W.1.3","W.1.8"],msg:"If an adult wrote the words for the student, note it. The writing checks still count, but the printing does not."},{t:"scribe",std:["W.1.2"],msg:"If an adult wrote the facts for the student, note it. The topic and the fact still count, but the printing does not."},{t:"passage",std:["RI.1.1"],msg:"If the six lines were read to the student, this stop shows listening, not reading. Rate it only if the student read the lines."},{t:"clock",std:["1.MD.B.3","2.MD.C.7"],msg:"The clock card names which hand is the hour and what each long hand position is worth, so a time read with it open is supported, not independent."},{t:"ruler",std:["1.MD.A.2","2.MD.A.1"],msg:"The ruler card shows the units already laid end to end from 0 and states the no gaps rule, so count a length found with it open as supported, not independent."},{t:"letters",std:["RF.1.3"],msg:"The letter and sound card lists the patterns and an example word for each, so a word sounded out with it open is supported, not independent."},{t:"letters",std:["RF.1.2"],msg:"RF.1.2 is listening only. If the card was open, note that the student had the blending and long vowel rules in front of them."},{t:"retell",std:["RL.1.1","SL.1.4","W.1.3"],msg:"The card gives the order words first, next and last, so count the order as supported and rate the details the student supplies."},{t:"qwords",std:["RL.1.1","RI.1.1","SL.1.2","L.1.1","K-2-ETS1-1"],msg:"The card supplies the question words, so a question asked with it open shows the student can use a word that was given, not that they thought of one alone."},{t:"mask",std:["RF.1.4"],msg:"A timed read with the reading window open is not a clean fluency baseline. Note in the stop notes that the lines were shown one at a time."}];return{stops:STOPS,levelups:LEVELUPS,tools:TOOLS,supCaveats:SUP_CAVEATS,passageStd:PASSAGE_STD}}});
